{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "In mice, high rapamycin levels were measured in brain after intraperitoneal administration, directly demonstrating that the rapamycin scaffold can cross the blood-brain barrier.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Preclinical studies in several species show rapamycin crosses the BBB, as measured by CSF and brain tissue levels or by inhibition of brain mTORC1 signaling.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Rapamycin was measured in human brain tumor tissue after daily systemic administration, confirming CNS access in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "One report describes rapamycin as having poor ability to traverse the BBB and observed no brain recombination, providing a contradictory signal.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a close rapamycin analog. Direct in vivo evidence from mice, multiple preclinical species, and humans shows that rapamycin reaches brain/CSF and inhibits brain mTOR, overriding the physicochemical prior. The single negative report is outweighed by repeated positive measurements.",
  "evidence_gaps": [
    "No direct experimental CNS exposure data for the exact query analog; extrapolation relies on the high transferability of rapamycin evidence.",
    "Unbound brain-to-plasma ratios and the quantitative contribution of efflux transporters are not fully defined.",
    "The query's specific substituent may alter transporter affinity or metabolic stability relative to rapamycin."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C14"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "rapamycin BBB penetration"
    }
  ],
  "revision_action": "initial"
}

